WITH base AS (SELECT *, CONCAT_WS('-', city, supplier_name) AS city_supplier_name_key FROM suppliers WHERE country IN ('US', 'JP', 'UK')), summary AS (SELECT CASE WHEN rating >= 4.0 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(CASE WHEN city = 'Singapore' THEN rating ELSE 0 END) AS singapore_rating FROM base GROUP BY CASE WHEN rating >= 4.0 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END) SELECT rating_bucket, singapore_rating FROM summary WHERE singapore_rating > 65 ORDER BY singapore_rating DESC;
